324	    /** Defer an OPEN claim until a date after the sheet's today: until then it counts in no total, is not overdue,
325	     * cannot be settled and is left unbound by a statement. A claim that is not OPEN, a date not after today, or
326	     * a claim dated in a closed period, is refused. */
327	    @Transactional
328	    public Claim defer(String user, String sheetId, Long id, LocalDate until) {
329	        LocalDate today = sheets.today(sheetId);
330	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
331	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
332	        requireOpenPeriod(sheetId, claim.getDate());
333	        if (claim.getStatus() != ClaimStatus.OPEN) {
334	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be deferred.");
335	        }
336	        if (!until.isAfter(today)) {
337	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A claim is deferred to a date after today.");
338	        }
339	        Person person = requirePerson(sheetId, claim.getPersonId());
340	        Snapshot before = rollup.snapshot(sheetId);
341	        claim.setDeferredUntil(until);
342	        claims.flush();
343	        audit.recordOnCommit(entry("CLAIM_DEFERRED", user, person, claim) + " until=" + until);
344	        rollup.recordChanges(user, sheetId, before);
345	        return claim;
