348	    /** A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a statement bound
349	     * it to stays bound; its period follows the new date and, with period numbering, a claim whose period changes
350	     * takes the next number of its new period's sequence, its old number never given out again. A claim of any
351	     * other status, one dated in a closed period or a new date inside one, a date after its person's retirement,
352	     * or anyone but a steward, is refused. */
353	    @Transactional
354	    public Claim redate(String user, String sheetId, Long id, LocalDate date) {
355	        sheets.today(sheetId); // the sheet must exist
356	        // Locking the sheet before taking the number numbers claims one at a time.
357	        sheets.lock(sheetId);
358	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
359	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
360	        settings.requireSteward(sheetId, user);
361	        if (!claim.getStatus().isOpen()) {
362	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN or PENDING claim can be re-dated.");
363	        }
364	        requireOpenPeriod(sheetId, claim.getDate());
365	        requireOpenPeriod(sheetId, date);
366	        Person person = requirePerson(sheetId, claim.getPersonId());
367	        requireNotRetired(person, date);
368	        Snapshot before = rollup.snapshot(sheetId);
369	        LocalDate old = claim.getDate();
370	        boolean periodChanged = !periods.periodOf(sheetId, old).map(Period::getId)
371	                .equals(periods.periodOf(sheetId, date).map(Period::getId));
372	        claim.setDate(date);
373	        if (periodChanged && claim.getNumber() != null && sheets.numbersByPeriod(sheetId)) {
374	            claim.renumber(nextNumber(sheetId, claim));
375	        }
376	        claims.flush();
377	        audit.recordOnCommit(entry("CLAIM_REDATED", user, person, claim) + " old=" + old + " new=" + date);
378	        rollup.recordChanges(user, sheetId, before);
379	        return claim;
380	    }
