382	    /** Split an amount off an OPEN claim: more than 0.00 and less than its amount. The claim keeps the rest and
383	     * loses any figure a statement bound it to; a new OPEN claim of the amount split off, with the same date and
384	     * note, takes the next number, is opened by the user, has its due-by fixed now from the terms in force on the
385	     * date, and names the claim it was split from. A claim that is not OPEN (PENDING, settled, ...), is deferred,
386	     * or is dated in a closed period, is refused. */
387	    @Transactional
388	    public Split split(String user, String sheetId, Long id, BigDecimal amount) {
389	        LocalDate today = sheets.today(sheetId);
390	        // Locking the sheet before taking the number numbers claims one at a time; a refused split rolls back and
391	        // gives the number back.
392	        sheets.lock(sheetId);
393	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
394	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
395	        requireOpenPeriod(sheetId, claim.getDate());
396	        if (claim.getStatus() != ClaimStatus.OPEN) {
397	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be split.");
398	        }
399	        if (claim.deferredOn(today)) {
400	            throw new ResponseStatusException(HttpStatus.CONFLICT,
401	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
402	        }
403	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
404	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
405	                    "The amount split off is more than 0.00 and less than the claim's amount.");
406	        }
407	        Person person = requirePerson(sheetId, claim.getPersonId());
408	        Snapshot before = rollup.snapshot(sheetId);
409	        claim.setAmount(claim.getAmount().subtract(amount));
410	        claim.unbind();
411	        LocalDate dated = claim.getDate();
412	        LocalDate dueBy = dueBy(sheetId, person, dated);
413	        Claim fresh = new Claim(sheetId, person.getId(), amount, dated, dueBy, claim.getNote());
414	        fresh.setSplitFrom(claim.getNumber());
415	        fresh.setStatus(ClaimStatus.OPEN);
416	        fresh.setNumber(nextNumber(sheetId, fresh));
417	        fresh.setOpenedBy(user);
418	        Claim split = claims.saveAndFlush(fresh);
419	        logStatus(user, today, split, person);
420	        claims.flush();
421	        audit.recordOnCommit(entry("CLAIM_SPLIT", user, person, claim) + " into=" + split.getNumber());
422	        audit.recordOnCommit(entry("CLAIM_OPENED", user, person, split));
423	        rollup.recordChanges(user, sheetId, before);
424	        return new Split(claim, split);
425	    }
