531	    /** Open the given claims of the sheet one at a time, in list order: people in the order they were added,
532	     * each one's claims newest first. Each is opened, and numbered, as {@link #changeStatus} would open it on its
533	     * own; one that cannot be opened (or is not on the sheet) is refused and left as it is. */
534	    public OpenedAll openAll(String user, String sheetId, List<Long> ids) {
535	        return changeAll(user, sheetId, ids, ClaimStatus.OPEN);
536	    }
