538	    /** Settle the given claims of the sheet one at a time, in list order, each as {@link #changeStatus} would
539	     * settle it on its own: one a clerk sends PENDING counts as settled; one that cannot be settled (or is not on
540	     * the sheet) is refused and left as it is. */
541	    public OpenedAll settleAll(String user, String sheetId, List<Long> ids) {
542	        return changeAll(user, sheetId, ids, ClaimStatus.SETTLED);
543	    }
544	
545	    /** Move the given claims to a status one at a time, in list order: people in the order they were added, each
546	     * one's claims newest first, each in its own transaction; one that is refused is left as it is. */
547	    private OpenedAll changeAll(String user, String sheetId, List<Long> ids, ClaimStatus next) {
548	        Set<Long> wanted = new HashSet<>(ids);
549	        List<Claim> chosen = transaction.execute(status -> {
550	            sheets.today(sheetId); // the sheet must exist
551	            Map<Long, Integer> personOrder = new HashMap<>();
552	            for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
553	                personOrder.put(person.getId(), personOrder.size());
554	            }
555	            return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
556	                    .filter(c -> wanted.contains(c.getId()))
557	                    .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
558	                    .toList();
559	        });
560	        List<Claim> changed = new ArrayList<>();
561	        if (settings.roleOf(sheetId, user) == Role.VIEWER || sheets.isArchived(sheetId)) {
562	            // A viewer, or anyone on an archived sheet, changes nothing: every claim is refused.
563	            return new OpenedAll(0, wanted.size(), changed);
564	        }
565	        for (Claim claim : chosen) {
566	            try {
567	                changed.add(transaction.execute(status -> changeStatus(user, sheetId, claim.getId(), next)));
568	            } catch (ResponseStatusException refused) {
569	                // Left as it is: its transaction rolled back, writing nothing.
570	            }
571	        }
572	        return new OpenedAll(changed.size(), wanted.size() - changed.size(), changed);
573	    }
