578	    /** The action of the permission matrix each status a claim is moved to takes. */
579	    private static final Map<ClaimStatus, Permission> PERMISSIONS = Map.of(
580	            ClaimStatus.OPEN, Permission.OPEN,
581	            ClaimStatus.SETTLED, Permission.SETTLE,
582	            ClaimStatus.VOID, Permission.VOID);
