596	    /** The number a claim opened now takes: the sheet's next number or, with period numbering in force, the next
597	     * in its period's own sequence, <period name>-<n>, or X-<n> for a claim in no period. */
598	    private String nextNumber(String sheetId, Claim claim) {
599	        if (!sheets.numbersByPeriod(sheetId)) {
600	            return String.valueOf(sheets.nextClaimNumber(sheetId));
601	        }
602	        String prefix = periods.periodOf(sheetId, claim.getDate()).map(Period::getName).orElse(NO_PERIOD) + "-";
603	        int last = 0;
604	        for (Claim other : claims.findBySheetIdOrderByIdDesc(sheetId)) {
605	            // A number a re-dated claim had before is never given out again.
606	            List<String> taken = new ArrayList<>(other.getFormerNumbers());
607	            taken.add(other.getNumber());
608	            for (String number : taken) {
609	                if (number != null && number.startsWith(prefix)) {
610	                    String rest = number.substring(prefix.length());
611	                    if (rest.matches("\\d{1,9}")) {
612	                        last = Math.max(last, Integer.parseInt(rest));
613	                    }
614	                }
615	            }
616	        }
617	        return prefix + (last + 1);
618	    }
