620	    /** The number a claim of this amount corrects: none unless the amount is negative, when it must name a
621	     * SETTLED claim of the same person, or the claim is refused. */
622	    private String correctedBy(String sheetId, Long personId, BigDecimal amount, String corrects) {
623	        if (amount.signum() >= 0) {
624	            return null;
625	        }
626	        String named = corrects == null ? null : corrects.trim();
627	        boolean settled = named != null && claims.findBySheetIdAndPersonId(sheetId, personId).stream()
628	                .anyMatch(c -> named.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
629	        if (!settled) {
630	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
631	                    "A correction must name a settled claim of the same person.");
632	        }
633	        return named;
634	    }
