package net.officefloor.hq.app.rate;


/** A rate for a grade on a sheet: a percent with two decimals, in force from its from-date (or from the
 * beginning of time when it has none), and applying through its to-date when it has one. */
@Entity
@Table(name = "rate")
public class Rate {

    /** Rates by from-date, the one with no from-date first. */
    public static final Comparator<Rate> BY_FROM =
            Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()));

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    @Column(name = "rate", nullable = false, precision = 5, scale = 2)
    private BigDecimal rate;

    protected Rate() {}

    public Rate(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal rate) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.to = to;
        this.rate = rate;
    }

    /** Of a grade's rates, the one in force on a date: the latest from-date on or before it, provided the date
     * is not after its to-date; none when the date is before every one, or after the to-date of that one. */
    public static Optional<Rate> inForce(Collection<Rate> rates, LocalDate date) {
        return rates.stream()
                .filter(r -> r.getFrom() == null || !r.getFrom().isAfter(date))
                .max(BY_FROM)
                .filter(r -> r.getTo() == null || !date.isAfter(r.getTo()));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    public void setTo(LocalDate to) {
        this.to = to;
    }

    public BigDecimal getRate() {
        return rate;
    }

    public void setRate(BigDecimal rate) {
        this.rate = rate;
    }
}
package net.officefloor.hq.app.rate;


@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, RollupService rollup, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's rates by grade, then from-date; a grade without one has no rate. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        sheets.today(sheetId); // the sheet must exist
        return rates.findBySheetId(sheetId).stream()
                .sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate.BY_FROM))
                .toList();
    }

    /** Set the rate for a grade from a from-date (none: from the beginning of time) through a to-date (none: with
     * no end), replacing any it had from that date. A to-date before the from-date is refused. */
    @Transactional
    public Rate set(String user, String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        sheets.today(sheetId); // the sheet must exist
        if (to != null && from != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "The to-date is before the from-date");
        }
        BigDecimal value = pct.setScale(2);
        Snapshot before = rollup.snapshot(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from).orElse(null);
        if (rate == null) {
            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, value));
        } else {
            rate.setRate(value);
            rate.setTo(to);
            rates.flush();
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                + " rate=" + value.toPlainString() + (from != null ? " from=" + from : "")
                + (to != null ? " to=" + to : ""));
        rollup.recordChanges(user, sheetId, before);
        return rate;
    }
}
package net.officefloor.hq.app.paste;


@Service
public class PasteService {

    /** The claim form's amount: up to two decimals; a negative one is a correction, which a line cannot name. */
    private static final String AMOUNT = "-?\\d{1,10}(\\.\\d{1,2})?";
    /** The claim form's longest note. */
    private static final int NOTE_MAX = 1000;

    /** A line read from the box: the person it names and the claim's amount, date (none for today) and note. */
    private record Line(Person person, BigDecimal amount, LocalDate date, String note) {}

    private final PersonRepository people;
    private final ClaimService claims;

    public PasteService(PersonRepository people, ClaimService claims) {
        this.people = people;
        this.claims = claims;
    }

    /** Add a draft claim per line of name,amount,date,note, in order, as the claim form would add it: the note
     * may hold commas or be absent, a blank date is the sheet's today, and the name must be on the sheet. Every
     * line is read first; it is one change, so one line refused (here or by the claim form's rules) adds none.
     * Blank lines are skipped; a box with no line is refused. */
    @Transactional
    public List<Claim> paste(String user, String sheetId, String text) {
        List<Line> lines = new ArrayList<>();
        String[] raw = text.split("\\r?\\n");
        for (int i = 0; i < raw.length; i++) {
            if (!raw[i].isBlank()) {
                lines.add(read(sheetId, raw[i], i + 1));
            }
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line.");
        }
        List<Claim> added = new ArrayList<>();
        for (Line line : lines) {
            added.add(claims.add(user, sheetId, line.person().getId(), line.amount(), line.date(), line.note(), null));
        }
        return added;
    }

    private Line read(String sheetId, String line, int number) {
        String[] fields = line.split(",", 4);
        if (fields.length < 2) {
            throw refused(number, "needs a name and an amount.");
        }
        String name = fields[0].trim();
        Person person = name.isEmpty() ? null : people.findByName(sheetId, name).orElse(null);
        if (person == null) {
            throw refused(number, "names no one on the sheet.");
        }
        String amount = fields[1].trim();
        if (!amount.matches(AMOUNT)) {
            throw refused(number, "needs an amount with up to two decimals.");
        }
        LocalDate date = null;
        if (fields.length > 2 && !fields[2].isBlank()) {
            try {
                date = LocalDate.parse(fields[2].trim());
            } catch (DateTimeParseException e) {
                throw refused(number, "needs a date as yyyy-mm-dd, or none.");
            }
        }
        String note = fields.length > 3 ? fields[3] : "";
        if (note.length() > NOTE_MAX) {
            throw refused(number, "has a note longer than " + NOTE_MAX + " characters.");
        }
        return new Line(person, new BigDecimal(amount), date, note);
    }

    private static ResponseStatusException refused(int number, String why) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + number + " " + why);
    }
}
package net.officefloor.hq.app.quickadd;


@Service
public class QuickAddService {

    /** The grade a person the quick-add creates is given. */
    static final String GRADE = "A";

    public record Added(Person person, boolean personCreated, Claim claim) {}

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    /** Add a draft claim dated the sheet's today with an empty note for the named person, creating them with
     * grade A first when the name is not on the sheet. It is one change: a refused claim leaves no new person. */
    @Transactional
    public Added add(String user, String sheetId, String name, BigDecimal amount) {
        String trimmed = name.trim();
        Person person = people.findByName(sheetId, trimmed).orElse(null);
        boolean created = person == null;
        if (created) {
            person = personService.add(user, sheetId, trimmed, GRADE);
        }
        Claim claim = claimService.add(user, sheetId, person.getId(), amount, null, "", null);
        return new Added(person, created, claim);
    }
}
